In some of our project we had: 
{code:xml} 
<dependency org="org" name="mymodule" rev="1.0" conf="compile,runtime->conf1" /> 
<dependency org="org" name="mymodule" rev="1.0" conf="compile,runtime->conf2" /> 
<dependency org="org" name="mymodule" rev="1.0" conf="compile,runtime->conf3" /> 
{code} 
When resolving dependencies with the conf "*", the resulting "compile" conf report did contain dependencies of the conf1, conf2 and conf3 of mymodule. But the resulting "runtime" conf report, contained only the configuration of conf3 of mymodule. 

Changing the dependency into the following one fixed it: 
{code:xml} 
<dependency org="org" name="mymodule" rev="1.0" conf="compile,runtime->conf1,conf2,conf3" /> 
{code}

{code} 
public ArtifactRevisionId(ArtifactId artfId, ModuleRevisionId mdlRevId, Map extraAttributes) { 
super(null, prepareExtraAttribute(artfId,extraAttributes)); //add "javadoc/sources" a maven2 classifier compatible 
artifactId = artfId; 
mrid = mdlRevId; 


setStandardAttribute(IvyPatternHelper.ORGANISATION_KEY, getModuleRevisionId() 
.getOrganisation()); 
setStandardAttribute(IvyPatternHelper.MODULE_KEY, getModuleRevisionId().getName()); 
setStandardAttribute(IvyPatternHelper.REVISION_KEY, getModuleRevisionId().getRevision()); 
setStandardAttribute(IvyPatternHelper.ARTIFACT_KEY, getName()); 
setStandardAttribute(IvyPatternHelper.TYPE_KEY, getType()); 
setStandardAttribute(IvyPatternHelper.EXT_KEY, getExt()); 
} 

public static Map prepareExtraAttribute(ArtifactId artfId,Map extraAttributes) { 
final String type = artfId.getType(); 
final String ext = artfId.getExt(); 
if((!("jar".equals(type))&&"jar".equals(ext) )&& (extraAttributes == null || !extraAttributes.containsKey("classifier"))){ 
if( extraAttributes == null){ 
extraAttributes = new HashMap(); 
}else{ 
extraAttributes = new HashMap(extraAttributes); 
} 
extraAttributes.put("m:classifier", type); 
} 
return extraAttributes; 
} 

{code} 

